var MATERIAL_IDS = Object.keys(MATERIALS);
function emptyStock() {
	return Object.fromEntries(MATERIAL_IDS.map((k) => [k, 0]));
}
/** Does `stock` cover `bill`? */
function hasAll(stock, bill) {
	for (const id in bill) if (!(stock[id] >= bill[id])) return false;
	return true;
}
/** What is still missing from `stock` to cover `bill`. */
function shortfall(stock, bill) {
	const out = {};
	for (const [id, n] of Object.entries(bill)) if (stock[id] < n) out[id] = n - stock[id];
	return out;
}
/** A quantity for people to read: whole numbers from 10 up, one decimal to 1, two below; null when it rounds to nothing. */
function qtyText(n) {
	if (n < .005) return null;
	if (n >= 10) return String(Math.round(n));
	if (n >= 1) return String(Math.round(n * 10) / 10);
	return (Math.round(n * 100) / 100).toString();
}
/** "3 lumber, 0.5 field seed": a bill or shortfall as text, skipping what rounds to zero. */
function billText(bill) {
	return Object.entries(bill).map(([k, n]) => {
		const q = qtyText(n);
		if (q === null) return null;
		if (k === "fuel") return `${litersText(n * 20)} of fuel`;
		return `${q} ${MATERIALS[k].name.toLowerCase()}`;
	}).filter(Boolean).join(", ");
}
/** "Waiting for ..." for a shortfall; a sliver that rounds to nothing still says so. */
var waitingFor = (miss) => `Waiting for ${billText(miss) || "a little more material"}`;
