	const survival = total ? alive / total : 0;
	const fed = st.days ? 1 - st.hungryDays / st.days : 1;
	const score = Math.round(100 * (.5 * survival + .2 * fed + .15 * (g.humanity / 100) + .15 * (g.raidsHeld + g.raidsLost ? g.raidsHeld / (g.raidsHeld + g.raidsLost) : 1)));
